/* Fixed-point per-part filter, included by instrument_audio.c (and used by the
 * global filter in instrument_fx.c). Controls 0..62 are a six-pole low-pass
 * filter, 63/64 an exact bypass, 65..127 a four-pole high-pass (TPT
 * state-variable filter). Cutoff and resonance laws are generated by
 * tools/gen_filter_ladder.py into instrument_filter_ladder.h. */
#ifndef BR_FILTER_MUL_SMALL32_PATH
#define BR_FILTER_MUL_SMALL32_PATH 1
#endif
/* instrument_fx.c tests this; the ladder is no longer optional. */
#define BR_FILTER_LADDER 1
#ifndef BR_FILTER_LADDER_COMP
#define BR_FILTER_LADDER_COMP 2048u /* Q12 bass compensation: input * (1 + comp*k) */
#endif
#ifndef BR_FILTER_LADDER_SAT_SCALE
/* Saturator x - x^3/(3*S^2), flat at |x| = S (output 2S/3). S = 53510 makes
 * 3*S^2 ~= 2^33 (the cubic then costs two multiplies) and compresses a
 * full-scale sine at the summing point by 0.85 dB. */
#define BR_FILTER_LADDER_SAT_SCALE 53510
#endif
#include "instrument_filter_ladder.h"

typedef struct {
    int32_t low;          /* last output of the side that was running (ladder restart point) */
    int32_t band;         /* unused by the track filter; kept zero */
    int32_t mix;          /* positive = LP, negative = HP; zero = exact bypass */
    int32_t ladder_s[4];  /* ladder stages or first high-pass, Q11/Q8 */
    int32_t extra_s[2], post_g, hp2_kinv, hp2_dinv; /* two post-ladder poles or second high-pass */
    int32_t ladder_g;     /* ladder: stage gain g/(1+g), Q30; high-pass: g, Q29; slewed */
    int32_t ladder_kinv;  /* ladder: k/(1+k*G^4), Q28, 0 = no feedback; high-pass: q + g, Q28 */
    int32_t ladder_dinv;  /* ladder: (1+comp*k)/(1+k*G^4), Q28; high-pass: 1/(1+q*g+g*g), Q30 */
    uint16_t ladder_k;    /* ladder: feedback k, Q12; high-pass: damping q = 1/Q, Q15 */
    uint8_t ladder_res;   /* resonance that ladder_k belongs to */
    uint8_t ladder_tick;  /* samples to the next coefficient update */
} br_filter_t;

/* Exact signed division by 2^shift with C truncation toward zero. This helper
 * is also used by the engine's native block-size-dependent output average. */
static int32_t br_filter_div_pow2(int32_t value, uint32_t shift)
{
    int32_t bias = value < 0 ? (int32_t)((1u << shift) - 1u) : 0;
    return (value + bias) >> shift;
}

static int32_t br_filter_mul_q15(int32_t x, uint32_t q)
{
#if BR_FILTER_MUL_SMALL32_PATH
    /* Source/part filter values usually occupy this interval. Both signs,
     * every Q15 coefficient and the truncation bias fit int32_t here. */
    if ((uint32_t)x + 65536u <= 131071u && q <= 32767u) {
        int32_t small = x * (int32_t)q;
        if (small < 0) small += 32767;
        return small >> 15;
    }
#endif
    int64_t product = (int64_t)x * (int32_t)q;
    if (product < 0) product += 32767;
    return (int32_t)(product >> 15);
}

static int32_t br_filter_slew(int32_t current, int32_t target)
{
    int32_t d = target - current;
#if FM1_NATIVE_OUTPUT_32K
    int32_t step = d / 6; /* 6 frames at 32 kHz ~= the original 8 at 44.1. */
#elif FM1_NATIVE_OUTPUT_48K
    int32_t step = d / 9; /* 9 frames at 48 kHz ~= the original 8 at 44.1. */
#else
    int32_t step = br_filter_div_pow2(d, 3u);
#endif
    if (!step && d) step = d > 0 ? 1 : -1;
    return current + step;
}

static void br_filter_init(br_filter_t *f)
{
    f->low = 0;
    f->band = 0;
    f->mix = 0;
    f->ladder_s[0] = f->ladder_s[1] = f->ladder_s[2] = f->ladder_s[3] = 0;
    f->extra_s[0] = f->extra_s[1] = f->post_g = f->hp2_kinv = f->hp2_dinv = 0;
    f->ladder_g = 1 << 29;
    f->ladder_kinv = 0;
    f->ladder_dinv = 1 << 28;
    f->ladder_k = 0u;
    f->ladder_res = 0u;
    f->ladder_tick = 16u;
}

/* Silent within two samples: the ladder's states are Q11, the high-pass's Q8. */
static int br_filter_quiet(const br_filter_t *f)
{
    int32_t lim = f->mix < 0 ? 512 : 4096;
    for (uint32_t i = 0u; i < 4u; ++i)
        if ((uint32_t)(f->ladder_s[i] + lim) > 2u * (uint32_t)lim) return 0;
    for (uint32_t i = 0u; i < 2u; ++i)
        if ((uint32_t)(f->extra_s[i] + lim) > 2u * (uint32_t)lim) return 0;
    return f->low >= -2 && f->low <= 2 && f->band >= -2 && f->band <= 2;
}

/* Move the cutoff with the note by `amount`/127 octave per octave (127: 1 oct/oct):
 * round((note - 60) * table steps per semitone * amount / 127) steps, clamped to
 * the table. The neutral 63/64 settings stay true bypasses regardless of key or
 * resonance. */
static uint32_t br_filter_keytrack(uint32_t control, uint32_t note, uint32_t amount)
{
    int32_t position, per_key;
    if (control >= 63u && control <= 64u) return control;
    if (note > 127u) note = 127u;
    if (amount > 127u) amount = 127u;
    position = control < 63u ? (int32_t)control : (int32_t)control - 65;
    per_key = (int32_t)(control < 63u ? BR_FILTER_LP_KEY_Q16 : BR_FILTER_HP_KEY_Q16);
    if (amount < 127u) per_key = per_key * (int32_t)amount / 127;
    position += (((int32_t)note - 60) * per_key + 32768) >> 16;
    if (position < 0) position = 0;
    if (position > 62) position = 62;
    return control < 63u ? (uint32_t)position : 65u + (uint32_t)position;
}

/* Four-pole low-pass ladder (Zavalishin, "The Art of VA Filter Design", ch. 5-6):
 * four TPT one-poles v = G*(x - s), y = v + s, s = y + v, with the feedback
 * u = x*(1 + comp*k) - k*y4 solved without a unit delay:
 *   u = ((1 + comp*k)*x - k*S) / (1 + k*G^4),
 * S being y4 for u = 0 (the stages' zero-input response). One cubic saturator
 * acts on u, so every state stays bounded whatever k is. k = 0 (resonance 0)
 * is the same ladder without the solve. States carry 11 fractional bits so
 * the lowest cutoffs neither step nor stall; silence walks them to zero. */
#define BR_FILTER_LADDER_SAT_LIMIT ((int32_t)BR_FILTER_LADDER_SAT_SCALE - 1)
/* The cube is taken of the magnitude in units of 2^SAT_E samples (< 65536). */
#if BR_FILTER_LADDER_SAT_SCALE < 65536
#define BR_FILTER_LADDER_SAT_E 0
#elif BR_FILTER_LADDER_SAT_SCALE < 262144
#define BR_FILTER_LADDER_SAT_E 2
#else
#error "BR_FILTER_LADDER_SAT_SCALE too large"
#endif
#define BR_FILTER_LADDER_SAT_RECIP ((uint32_t)((((uint64_t)1 << (48 + 3 * BR_FILTER_LADDER_SAT_E)) + \
    3ull * BR_FILTER_LADDER_SAT_SCALE * BR_FILTER_LADDER_SAT_SCALE / 2u) / \
    (3ull * BR_FILTER_LADDER_SAT_SCALE * BR_FILTER_LADDER_SAT_SCALE)))

static int32_t br_filter_ladder_mul(int32_t g, int32_t x)
{
    return (int32_t)(((int64_t)g * x) >> 30);
}

/* Control 0..62 -> stage gain: the table places the resonance-0 -3 dB point
 * geometrically from 20 Hz to the top of the rate (tools/gen_filter_ladder.py). */
static int32_t br_filter_ladder_target(uint32_t control)
{
#if FM1_NATIVE_OUTPUT_32K
    return br_filter_ladder_g_32k[control];
#elif FM1_NATIVE_OUTPUT_48K
    return br_filter_ladder_g_48k[control];
#else
    return br_filter_ladder_g[control];
#endif
}

/* Resonance 0..127 -> a value interpolated linearly between nodes at
 * r = 0, 8, ..., 128 (17 entries). */
static uint32_t br_filter_res_node(const uint16_t *node, uint32_t resonance)
{
    int32_t a = node[resonance >> 3], b = node[(resonance >> 3) + 1u];
    return (uint32_t)(a + (((b - a) * (int32_t)(resonance & 7u)) >> 3));
}

/* k from br_filter_ladder_k_nodes (Q12: the peak rises evenly in dB to k = 3.9
 * at r = 120; self-oscillation from r = 123), and the solve's 1/(1 + k*G^4)
 * folded into the feedback and input gains. Runs only when the gain or the
 * resonance moves, at most once per 16 samples. */
static void br_filter_ladder_coeffs(br_filter_t *f, uint32_t resonance)
{
    uint32_t k = f->ladder_k, g2, g4, inv;
    if (resonance != f->ladder_res) {
        k = br_filter_res_node(br_filter_ladder_k_nodes, resonance);
        f->ladder_res = (uint8_t)resonance;
        f->ladder_k = (uint16_t)k;
    }
    if (!k) {
        f->ladder_kinv = 0;
        return;
    }
    g2 = (uint32_t)(((uint64_t)(uint32_t)f->ladder_g * (uint32_t)f->ladder_g) >> 30);
    g4 = (uint32_t)(((uint64_t)g2 * g2) >> 44);
    inv = 0xFFFFFFFFu / (65536u + ((k * g4) >> 12));
    f->ladder_kinv = (int32_t)(k * inv);
    f->ladder_dinv = (int32_t)((4096u + ((BR_FILTER_LADDER_COMP * k) >> 12)) * inv);
}

/* Low-pass controls, and the fade out of a low-pass to dry (before bypass or a
 * high-pass). The ladder (re)starts from f->low (the dry signal after bypass,
 * the low-pass part of the outgoing high-pass) whenever it enters at dry. */
static int32_t br_filter_ladder(br_filter_t *f, int32_t input, uint32_t control,
                                uint32_t resonance)
{
    int32_t target_g = f->ladder_g, u, v, y, *s = f->ladder_s;
    if (resonance > 127u) resonance = 127u;
    if (control < 63u) target_g = br_filter_ladder_target(control);
    if (!f->mix || !f->ladder_tick) {
        s[0] = s[1] = s[2] = s[3] = f->low * 2048;
        f->extra_s[0] = f->extra_s[1] = f->low * 2048;
        f->band = 0;
        f->ladder_g = target_g;
        f->ladder_tick = 1u;
        f->ladder_res = 0xFFu; /* coefficients now, below */
    }
    f->mix = br_filter_slew(f->mix, control < 63u ? 32767 : 0);
    if (!--f->ladder_tick) {
        f->ladder_tick = 16u;
        if (f->ladder_g != target_g || f->ladder_res != resonance) {
            /* 1/16 of the distance per 16 samples: a ~256-sample glide. */
            int32_t d = target_g - f->ladder_g, step = d >> 4;
            f->ladder_g += step ? step : d;
            br_filter_ladder_coeffs(f, resonance);
            f->post_g = (int32_t)(((uint64_t)(uint32_t)f->ladder_g * 2u << 30) /
                                  ((1u << 30) + (uint32_t)f->ladder_g));
        }
    }
    if (input > 262144) input = 262144;
    if (input < -262144) input = -262144;
    if (!input) {
#pragma clang loop unroll(disable)
        for (uint32_t i = 0u; i < 4u; ++i)
            if (s[i]) s[i] += s[i] > 0 ? -1 : 1;
        for (uint32_t i = 0u; i < 2u; ++i)
            if (f->extra_s[i]) f->extra_s[i] += f->extra_s[i] > 0 ? -1 : 1;
    }
    if (f->ladder_kinv) {
        /* Each term fits int32 (|input| <= 2^18, |S| < 2^30); taken in Q10 so
         * their difference does too, clamped, then back to Q11. */
        int32_t z = s[0] - br_filter_ladder_mul(f->ladder_g, s[0]);
        z = s[1] + br_filter_ladder_mul(f->ladder_g, z - s[1]);
        z = s[2] + br_filter_ladder_mul(f->ladder_g, z - s[2]);
        z = s[3] + br_filter_ladder_mul(f->ladder_g, z - s[3]);
        u = (int32_t)(((int64_t)f->ladder_dinv * input) >> 18) -
            (int32_t)(((int64_t)f->ladder_kinv * z) >> 29);
        if (u > BR_FILTER_LADDER_SAT_LIMIT * 1024) u = BR_FILTER_LADDER_SAT_LIMIT * 1024;
        if (u < -BR_FILTER_LADDER_SAT_LIMIT * 1024) u = -BR_FILTER_LADDER_SAT_LIMIT * 1024;
        u *= 2;
    } else {
        u = input * 2048;
        if (u > BR_FILTER_LADDER_SAT_LIMIT * 2048) u = BR_FILTER_LADDER_SAT_LIMIT * 2048;
        if (u < -BR_FILTER_LADDER_SAT_LIMIT * 2048) u = -BR_FILTER_LADDER_SAT_LIMIT * 2048;
    }
    {
        /* Odd, monotonic soft clip m - m^3/(3*S^2) on the magnitude. */
        uint32_t m = u < 0 ? (uint32_t)-u : (uint32_t)u, t = m >> (11 + BR_FILTER_LADDER_SAT_E), cube;
        cube = (uint32_t)(((uint64_t)(t * t) * t) >> 16);
        m -= (uint32_t)(((uint64_t)cube * BR_FILTER_LADDER_SAT_RECIP) >> 32) << 11;
        u = u < 0 ? -(int32_t)m : (int32_t)m;
    }
    v = br_filter_ladder_mul(f->ladder_g, u - s[0]); y = s[0] + v; s[0] = y + v;
    v = br_filter_ladder_mul(f->ladder_g, y - s[1]); y = s[1] + v; s[1] = y + v;
    v = br_filter_ladder_mul(f->ladder_g, y - s[2]); y = s[2] + v; s[2] = y + v;
    v = br_filter_ladder_mul(f->ladder_g, y - s[3]); y = s[3] + v; s[3] = y + v;
    v = br_filter_ladder_mul(f->post_g, y - f->extra_s[0]); y = f->extra_s[0] + v; f->extra_s[0] = y + v;
    v = br_filter_ladder_mul(f->post_g, y - f->extra_s[1]); y = f->extra_s[1] + v; f->extra_s[1] = y + v;
    y = (y + 1024) >> 11;
    f->low = y;
    if (f->mix > 0) return input + br_filter_mul_q15(y - input, (uint32_t)f->mix);
    /* The fade has reached dry: bypass or the high-pass takes over. */
    s[0] = s[1] = s[2] = s[3] = 0;
    f->extra_s[0] = f->extra_s[1] = 0;
    return input;
}

/* Four-pole high-pass: two TPT state-variable stages (Zavalishin, "The Art of
 * VA Filter Design", ch. 4), the same at every resonance:
 *   hp = (x - (q + g)*s1 - s2) / (1 + q*g + g*g),
 *   v = g*hp, band = v + s1, s1 = band + v; v = g*band, low = v + s2, s2 = low + v,
 * g = tan(pi*fc/fs) (br_filter_hp_g), q = 1/Q (br_filter_hp_q_nodes: Butterworth
 * at resonance 0, peak +16 dB at 127). It is stable for every g > 0, q > 0, so
 * no cutoff cap is needed; the peak sits at the cutoff at every setting. States
 * are Q8, clipped to +-2^18 samples; with |x| <= 2^18 and g <= 1.15 every
 * intermediate fits int32. Silence walks the states to zero. */
#define BR_FILTER_HP_STATE_LIMIT (1 << 26)

static int32_t br_filter_hp_target(uint32_t position)
{
#if FM1_NATIVE_OUTPUT_32K
    return br_filter_hp_g_32k[position];
#elif FM1_NATIVE_OUTPUT_48K
    return br_filter_hp_g_48k[position];
#else
    return br_filter_hp_g[position];
#endif
}

/* Runs only when g or the resonance moves, at most once per 16 samples. */
static void br_filter_hp_coeffs(br_filter_t *f, uint32_t resonance)
{
    uint32_t q = f->ladder_k, g = (uint32_t)f->ladder_g >> 14, den;
    if (resonance != f->ladder_res) {
        q = br_filter_res_node(br_filter_hp_q_nodes, resonance);
        f->ladder_res = (uint8_t)resonance;
        f->ladder_k = (uint16_t)q;
    }
    den = 65536u + ((q * g) >> 14) + ((g * g) >> 14);       /* Q16 */
    f->ladder_kinv = (int32_t)((q + g) << 13);
    f->ladder_dinv = (int32_t)((0xFFFFFFFFu / den) << 14);
    /* The second high-pass stage has fixed Butterworth damping; resonance
     * stays in the first stage rather than doubling its peak. */
    g >>= 1; /* second stage has half the primary cutoff */
    den = 65536u + ((46341u * g) >> 14) + ((g * g) >> 14);
    f->hp2_kinv = (int32_t)((46341u + g) << 13);
    f->hp2_dinv = (int32_t)((0xFFFFFFFFu / den) << 14);
}

/* High-pass controls, and the fade out of a high-pass to dry. Entered at dry,
 * it starts with its low state at the dry signal, so its output starts at 0. */
static int32_t br_filter_hp(br_filter_t *f, int32_t input, uint32_t control,
                            uint32_t resonance)
{
    int32_t target_g = f->ladder_g, target_mix = control > 64u ? -32767 : 0;
    int32_t *s = f->ladder_s, t, hp, v, band, low;
    if (resonance > 127u) resonance = 127u;
    if (control > 64u) target_g = br_filter_hp_target(control - 65u);
    if (!f->mix) {
        s[0] = s[2] = s[3] = 0;
        f->extra_s[0] = f->extra_s[1] = 0;
        s[1] = f->low * 256;
        f->low = 0;
        f->ladder_g = target_g;
        f->ladder_tick = 1u;
        f->ladder_res = 0xFFu; /* coefficients now, below */
    }
    if (f->mix != target_mix) f->mix = br_filter_slew(f->mix, target_mix);
    if (!--f->ladder_tick) {
        f->ladder_tick = 16u;
        if (f->ladder_g != target_g || f->ladder_res != resonance) {
            int32_t d = target_g - f->ladder_g, step = d >> 4;
            f->ladder_g += step ? step : d;
            br_filter_hp_coeffs(f, resonance);
        }
    }
    if (input > 262144) input = 262144;
    if (input < -262144) input = -262144;
    if (!input) {
        if (s[0]) s[0] += s[0] > 0 ? -1 : 1;
        if (s[1]) s[1] += s[1] > 0 ? -1 : 1;
        for (uint32_t i = 0; i < 2u; ++i)
            if (f->extra_s[i]) f->extra_s[i] += f->extra_s[i] > 0 ? -1 : 1;
    }
    t = input * 256 - (int32_t)(((int64_t)f->ladder_kinv * s[0]) >> 28) - s[1];
    hp = (int32_t)(((int64_t)f->ladder_dinv * t) >> 30);
    v = (int32_t)(((int64_t)f->ladder_g * hp) >> 29);
    band = s[0] + v;
    s[0] = band + v;
    v = (int32_t)(((int64_t)f->ladder_g * band) >> 29);
    low = s[1] + v;
    s[1] = low + v;
    if (s[0] > BR_FILTER_HP_STATE_LIMIT) s[0] = BR_FILTER_HP_STATE_LIMIT;
    if (s[0] < -BR_FILTER_HP_STATE_LIMIT) s[0] = -BR_FILTER_HP_STATE_LIMIT;
    if (s[1] > BR_FILTER_HP_STATE_LIMIT) s[1] = BR_FILTER_HP_STATE_LIMIT;
    if (s[1] < -BR_FILTER_HP_STATE_LIMIT) s[1] = -BR_FILTER_HP_STATE_LIMIT;
    if (hp > BR_FILTER_HP_STATE_LIMIT) hp = BR_FILTER_HP_STATE_LIMIT;
    if (hp < -BR_FILTER_HP_STATE_LIMIT) hp = -BR_FILTER_HP_STATE_LIMIT;
    t = hp - (int32_t)(((int64_t)f->hp2_kinv * f->extra_s[0]) >> 28) - f->extra_s[1];
    hp = (int32_t)(((int64_t)f->hp2_dinv * t) >> 30);
    v = (int32_t)(((int64_t)(f->ladder_g >> 1) * hp) >> 29);
    band = f->extra_s[0] + v; f->extra_s[0] = band + v;
    v = (int32_t)(((int64_t)(f->ladder_g >> 1) * band) >> 29);
    f->extra_s[1] += v + v;
    for (uint32_t i = 0u; i < 2u; ++i) {
        if (f->extra_s[i] > BR_FILTER_HP_STATE_LIMIT) f->extra_s[i] = BR_FILTER_HP_STATE_LIMIT;
        if (f->extra_s[i] < -BR_FILTER_HP_STATE_LIMIT) f->extra_s[i] = -BR_FILTER_HP_STATE_LIMIT;
    }
    hp = (hp + 128) >> 8;
    if (f->mix == -32767) return hp;
    if (!target_mix) f->low = (low + 128) >> 8; /* fading out: where a following low-pass starts */
    if (f->mix) return input + br_filter_mul_q15(hp - input, (uint32_t)-f->mix);
    s[0] = s[1] = 0; f->extra_s[0] = f->extra_s[1] = 0;
    return input;
}

static int32_t br_filter_run(br_filter_t *f, int32_t input, uint32_t control,
                             uint32_t resonance)
{
    if (control < 63u ? f->mix >= 0 : f->mix > 0)
        return br_filter_ladder(f, input, control, resonance);
    if (control > 64u || f->mix)
        return br_filter_hp(f, input, control, resonance);
    if (input > 262144) input = 262144;
    if (input < -262144) input = -262144;
    f->low = input;
    return input;
}

/* Resonance 0 (the engine's path when resonance and key tracking are off). */
static int32_t br_filter_process(br_filter_t *f, int32_t input, uint32_t control)
{
    return br_filter_run(f, input, control, 0u);
}

static int32_t br_filter_process_controls(br_filter_t *f, int32_t input,
                                          uint32_t control,
                                          uint32_t resonance,
                                          uint32_t keytrack,
                                          uint32_t note)
{
    if (control > 127u) control = 127u;
    if (keytrack) control = br_filter_keytrack(control, note, keytrack);
    return br_filter_run(f, input, control, resonance);
}
